def predict_pairwise(inp, color):
    R=len(inp); C=len(inp[0])
    # group runs by u=c-r, consecutive rows
    groups=[]
    byu=defaultdict(list)
    for r,row in enumerate(inp):
      for c,x in enumerate(row):
       if x==color:byu[c-r].append((r,c,c+r))
    for u,pts in byu.items():
      pts=sorted(pts)
      gs=[]
      for p in pts:
        if not gs or p[0]!=gs[-1][-1][0]+1:gs.append([p])
        else:gs[-1].append(p)
      for g in gs:groups.append((u,min(x[2] for x in g),max(x[2] for x in g)))
    out=[row[:] for row in inp]
    for i,(u1,l1,h1) in enumerate(groups):
      for u2,l2,h2 in groups[i+1:]:
        lo,hi=sorted((u1,u2)); vlo=max(l1,l2);vhi=min(h1,h2)
        for r in range(R):
          for c in range(C):
            if lo<c-r<hi and vlo<=c+r<=vhi and inp[r][c]==8:out[r][c]=2
    return out,groups
